# name: arithmetic_relation_target_excess
# description: Yes rate for non-example targets equal to the sum or difference of two examples minus the yes rate of other non-example targets in the same sets (sets with 2+ examples); observed > null means people use arithmetic relations between examples that the model's concepts lack.
def test_statistic(df):
    sets = df["number_set"].unique()
    rel = {}
    exs = {}
    for s in sets:
        l = [int(x) for x in s.split(",")]
        exs[s] = set(l)
        r = set()
        for i in range(len(l)):
            for j in range(len(l)):
                if i != j:
                    r.add(l[i] + l[j]); r.add(abs(l[i] - l[j]))
        rel[s] = r
    items = df.groupby(["number_set", "target"])["rating"].mean().reset_index()
    multi = items["number_set"].map(lambda s: len(exs[s]) >= 2).to_numpy()
    is_rel = np.array([t in rel[s] for s, t in zip(items["number_set"], items["target"])])
    is_ex = np.array([t in exs[s] for s, t in zip(items["number_set"], items["target"])])
    a = items["rating"][multi & is_rel & ~is_ex]
    b = items["rating"][multi & ~is_rel & ~is_ex]
    if len(a) == 0 or len(b) == 0:
        return 0.0
    return float(a.mean() - b.mean())

# name: offrule_residue_class_contrast
# description: Among sets of 3+ examples whose pairwise differences share a gcd d >= 4 (d != 10) but which are not multiples of d (e.g. 33,17,5,9 = 1 mod 4), yes rate for non-example targets in the same residue class mod d minus targets outside it; observed > null means people detect "same remainder" regularities the model has no concept for.
def test_statistic(df):
    sets = df["number_set"].unique()
    info = {}
    for s in sets:
        l = [int(x) for x in s.split(",")]
        if len(l) < 3:
            continue
        g = 0
        for a in l[1:]:
            g = math.gcd(g, abs(a - l[0]))
        if g >= 4 and g != 10 and l[0] % g != 0:
            info[s] = (g, l[0] % g, set(l))
    if not info:
        return 0.0
    sub = df[df["number_set"].isin(list(info))]
    items = sub.groupby(["number_set", "target"])["rating"].mean().reset_index()
    inres = np.array([t % info[s][0] == info[s][1] for s, t in zip(items["number_set"], items["target"])])
    isex = np.array([t in info[s][2] for s, t in zip(items["number_set"], items["target"])])
    a = items["rating"][inres & ~isex]
    b = items["rating"][~inres & ~isex]
    if len(a) == 0 or len(b) == 0:
        return 0.0
    return float(a.mean() - b.mean())

# name: between_set_yes_variance
# description: Variance across sets (with >= 10 trials) of the set-level yes rate; observed > null means people's breadth of generalisation differs between sets more than the model predicts (some sets far broader/narrower), observed < null means the model makes set breadths too heterogeneous.
def test_statistic(df):
    g = df.groupby("number_set")["rating"].agg(["mean", "size"])
    g = g[g["size"] >= 10]
    if len(g) < 2:
        return 0.0
    return float(g["mean"].var())

# name: digit_reversal_target_excess
# description: Yes rate for targets that are the digit reversal of an example (e.g. 13 -> 31) minus the yes rate of other non-example targets in the same sets; observed > null means people generalise to digit-reversed numbers more than the model's rule/interval concepts predict.
def test_statistic(df):
    sets = df["number_set"].unique()
    revs = {}
    exs = {}
    for s in sets:
        l = [int(x) for x in s.split(",")]
        exs[s] = set(l)
        revs[s] = {int(str(e)[::-1]) for e in l if e >= 10 and e % 10 != 0 and str(e) != str(e)[::-1]}
    items = df.groupby(["number_set", "target"])["rating"].mean().reset_index()
    is_rev = np.array([t in revs[s] for s, t in zip(items["number_set"], items["target"])])
    is_ex = np.array([t in exs[s] for s, t in zip(items["number_set"], items["target"])])
    has = items["number_set"].map(lambda s: len(revs[s]) > 0).to_numpy()
    a = items["rating"][is_rev & ~is_ex]
    b = items["rating"][has & ~is_rev & ~is_ex]
    if len(a) == 0 or len(b) == 0:
        return 0.0
    return float(a.mean() - b.mean())

# name: prime_set_prime_vs_odd_composite
# description: Among sets of 2+ examples that are all odd primes, yes rate for prime targets minus odd composite targets (non-examples); observed > null means people pick out "primes" over "odd numbers" more sharply than the model, observed < null means the model over-commits to the primes rule.
def test_statistic(df):
    def isp(n):
        return n > 1 and all(n % a for a in range(2, int(n ** 0.5) + 1))
    primes = {n for n in range(1, 101) if isp(n)}
    sets = df["number_set"].unique()
    keep = {}
    for s in sets:
        l = [int(x) for x in s.split(",")]
        if len(l) >= 2 and all(e in primes and e > 2 for e in l):
            keep[s] = set(l)
    if not keep:
        return 0.0
    sub = df[df["number_set"].isin(list(keep))]
    items = sub.groupby(["number_set", "target"])["rating"].mean().reset_index()
    t = items["target"].astype(int).to_numpy()
    isex = np.array([tt in keep[s] for s, tt in zip(items["number_set"], t)])
    ip = np.isin(t, list(primes))
    oc = (t % 2 == 1) & ~ip & (t > 1)
    a = items["rating"][ip & ~isex]
    b = items["rating"][oc & ~isex]
    if len(a) == 0 or len(b) == 0:
        return 0.0
    return float(a.mean() - b.mean())

# name: shared_nonlast_digit_contrast
# description: Among sets of 2+ examples that share a common digit but not a common last digit (e.g. 13,91 share 1), yes rate for non-example targets containing a shared digit minus targets containing none; observed > null means people lean on "contains digit" similarity more than the model, observed < null means the model over-uses contains-digit rules.
def test_statistic(df):
    sets = df["number_set"].unique()
    info = {}
    for s in sets:
        l = [int(x) for x in s.split(",")]
        if len(l) < 2 or len({e % 10 for e in l}) == 1:
            continue
        c = set(str(l[0]))
        for e in l[1:]:
            c &= set(str(e))
        if c:
            info[s] = (c, set(l))
    if not info:
        return 0.0
    sub = df[df["number_set"].isin(list(info))]
    items = sub.groupby(["number_set", "target"])["rating"].mean().reset_index()
    has = np.array([bool(set(str(t)) & info[s][0]) for s, t in zip(items["number_set"], items["target"])])
    isex = np.array([t in info[s][1] for s, t in zip(items["number_set"], items["target"])])
    a = items["rating"][has & ~isex]
    b = items["rating"][~has & ~isex]
    if len(a) == 0 or len(b) == 0:
        return 0.0
    return float(a.mean() - b.mean())

# name: small_rule_hull_exception_yes
# description: Among sets of 2+ examples that all fall in one small rule (<= 12 members: squares, cubes, powers of k, multiples of 9/11/12), yes rate for non-rule targets lying inside the examples' range; observed > null means people fill in the numeric range around tight-rule sets more than the model (its size principle is too sharp), observed < null means less.
def test_statistic(df):
    rules = [[n * n for n in range(1, 11)], [n ** 3 for n in range(1, 5)]]
    rules += [[m ** k for k in range(1, 8) if m ** k <= 100] for m in range(2, 11)]
    rules += [list(range(m, 101, m)) for m in [9, 11, 12]]
    rules = [set(r) for r in rules if len(r) >= 2]
    sets = df["number_set"].unique()
    info = {}
    for s in sets:
        l = [int(x) for x in s.split(",")]
        if len(l) < 2:
            continue
        fits = [r for r in rules if set(l) <= r]
        if fits:
            info[s] = (min(l), max(l), set().union(*fits))
    if not info:
        return 0.0
    sub = df[df["number_set"].isin(list(info))]
    items = sub.groupby(["number_set", "target"])["rating"].mean().reset_index()
    m = np.array([(info[s][0] < t < info[s][1]) and (t not in info[s][2])
                  for s, t in zip(items["number_set"], items["target"].astype(int))])
    if m.sum() == 0:
        return 0.0
    return float(items["rating"][m].mean())
